package com.ke.ticketsystemke.service;import com.ke.ticketsystemke.repository.WarrantyAttachmentRepository;import com.ke.ticketsystemke.storage.WarrantyFileStorage;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.time.*;import java.time.temporal.ChronoUnit;
@Service public class WarrantyAttachmentRetentionService{private static final Logger log=LoggerFactory.getLogger(WarrantyAttachmentRetentionService.class);private final WarrantyAttachmentRepository attachments;private final WarrantyFileStorage storage;private final int days;public WarrantyAttachmentRetentionService(WarrantyAttachmentRepository a,WarrantyFileStorage s,@Value("${warranty.files.retention-days:90}")int days){attachments=a;storage=s;this.days=days;}
 /** Deliberately not scheduled or exposed as an endpoint; invoke only from a reviewed SUPER_ADMIN operation. */
 public CleanupResult cleanupExpiredInactive(){int removed=0,missing=0,failed=0;for(var a:attachments.findByActiveFalseAndDeactivatedAtBefore(Instant.now().minus(days,ChronoUnit.DAYS))){if(a.isActive()){failed++;continue;}try{if(!storage.exists(a.getStorageKey())){missing++;log.warn("event=warranty_file_cleanup_missing attachmentId={}",a.getId());continue;}storage.deletePermanent(a.getStorageKey());removed++;log.info("event=warranty_file_cleanup_success attachmentId={}",a.getId());}catch(Exception e){failed++;log.error("event=warranty_file_cleanup_failed attachmentId={}",a.getId());}}return new CleanupResult(removed,missing,failed);}public record CleanupResult(int removed,int missing,int failed){}
}
